SELECT g.id, g.order_no, g.goods_id, g.goods_name, g.goods_image, g.price, g.seller_id, g.buyer_id, g.receiver_name, g.receiver_phone, g.receiver_address, g.status, g.ship_company, g.ship_no, g.ship_time, g.finish_time, g.cancel_time, g.create_time FROM goods_order g
g.buyer_id = #{userId}
g.seller_id = #{userId}
ORDER BY g.create_time DESC
